let
  type intlist = { head: int, tail: intlist }
  function sum(l: intlist): int =
    if l = nil then 0
    else l.head + sum(l.tail)
  var l := intlist { head = 1,
           tail = intlist { head = 2, tail = nil } }
in
  print_int(sum(l))
end

#define DEADBAND 20

void loop(void) {
    int left  = read_avg(ADC_LEFT,  8);
    int right = read_avg(ADC_RIGHT, 8) + calib_offset;
    int err   = left - right;

    if (abs(err) < DEADBAND) {
        motor_stop();
    } else {
        int speed = clamp(abs(err) * KP, PWM_MIN, PWM_MAX);
        motor_set(err > 0 ? DIR_LEFT : DIR_RIGHT, speed);
    }
}

__global__ void diff_threshold(const uchar3* frame, const float3* bg,
                               uint8_t* mask, int w, int h, float th)
{
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    if (x >= w || y >= h) return;

    int i = y * w + x;
    float3 d = make_float3(frame[i].x - bg[i].x,
                           frame[i].y - bg[i].y,
                           frame[i].z - bg[i].z);
    float dist = sqrtf(d.x*d.x + d.y*d.y + d.z*d.z);
    mask[i] = dist > th ? 255 : 0;
}

static bool is_stationary(const imu_sample_t *s)
{
    float a_norm = vec3_norm(s->acc);          // en g
    float w_norm = vec3_norm(s->gyro);         // en rad/s
    return fabsf(a_norm - 1.0f) < ACC_TH && w_norm < GYRO_TH;
}

void process(imu_sample_t *s, float dt)
{
    madgwick_update(&q, s->gyro, s->acc, BETA, dt);
    vec3 a_world = quat_rotate(q, s->acc);
    a_world.z -= 1.0f;                         // retire la gravité

    if (window_all(is_stationary)) vel = VEC3_ZERO;   // ZUPT
    else vel = vec3_add(vel, vec3_scale(a_world, G * dt));

    pos = vec3_add(pos, vec3_scale(vel, dt));
}

// Allume la LED reliée entre la broche `hi` (anode) et `lo` (cathode)
static void led_on(uint8_t hi, uint8_t lo)
{
    PIN_DDR  = 0;                    // toutes les broches en haute impédance
    PIN_PORT = 0;
    PIN_DDR  = (1 << hi) | (1 << lo);// seules hi et lo deviennent des sorties
    PIN_PORT = (1 << hi);            // hi = 1, lo = 0 -> courant dans la LED
}

ISR(TIMER_vect)                       // rafraîchissement de l'écran
{
    static uint8_t i = 0;
    if (framebuffer[i]) led_on(led_map[i].hi, led_map[i].lo);
    else                PIN_DDR = 0;
    i = (i + 1) % NB_LEDS;
}

entity alu is
  port (
    op     : in  std_logic_vector(1 downto 0);
    a, b   : in  std_logic_vector(31 downto 0);
    s      : out std_logic_vector(31 downto 0);
    n_flag : out std_logic
  );
end entity;

architecture rtl of alu is
  signal res : signed(31 downto 0);
begin
  with op select res <=
    signed(a) + signed(b) when "00",
    signed(b)             when "01",
    signed(a) - signed(b) when "10",
    signed(a)             when others;

  s      <= std_logic_vector(res);
  n_flag <= res(31);
end architecture;

